INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::Amplitude','struct','Holds an element of `ℤ[1/√2, i]` at its least scale, so equal amplitudes have equal forms and the gates act exactly.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::Amplitudes','struct','Holds the generated elements of the ring `ℤ[1/√2, i]` under the discrete order, so its ring laws are checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::Coefficient','struct','Names an integer coefficient of an amplitude, so the coefficients of a form are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::RealAmplitude','struct','Holds an element of the real subring `ℤ[1/√2]` at its least scale, so a squared modulus is read exactly.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::RealAmplitudes','struct','Holds the generated elements of the ring `ℤ[1/√2]` under the discrete order, so its ring laws are checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','amplitude::Scale','struct','Names the exponent of the power of two that divides an amplitude, so the scale of a form is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','cover::Chart','struct','Names the position of one chart in a cover, so a refusal says which chart or overlap fails.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','cover::Cocycle','struct','Holds a Čech cocycle on a cover as a numerator for each ordered pair of charts, so the cover splits it.','sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','cover::Cover','struct','Holds a unimodular sequence with its coefficients, replayed with no search, so local sections glue and a cocycle splits by the partition of unity.','oracle sharing','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','cover::CoverRefusal','enum','Names why a cover, a gluing or a splitting refused: a count that differs, a chart or a combination that fails, or an operation past the represented elements.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','gate::CircuitRefusal','enum','Names why a register refused a step: too many qubits, an absent or repeated qubit, or an amplitude past the integers.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','gate::Gate','struct','Holds a square matrix over exact amplitudes, so a gate multiplies, takes its adjoint and acts on a state exactly.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','gate::QubitCount','struct','Names how many qubits a register holds, so the width of a state is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','gate::QubitIndex','struct','Names one qubit of a register, so a gate says which qubits it acts on.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','gate::State','struct','Holds the exact amplitudes of the basis states of a register, so a circuit of gates runs on it with no rounding.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','instance::Distance','struct','Holds an element of the Lawvere quantale, a non-negative exact dyadic or infinity, so a distance''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','instance::Lawvere','struct','Holds the generated elements of the Lawvere quantale, whose minimum adds and whose sum multiplies under the reverse order, so its laws are checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','instance::MaxPlus','enum','Names an element of the max-plus semiring, an exact dyadic or minus infinity, so the element''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','instance::NegativeDistance','struct','Names a dyadic below zero that a distance refused, so the refused value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','instance::Tropical','struct','Holds the generated elements of the max-plus semiring over exact dyadics, so its laws are checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::Arity','enum','Names how many elements a law quantifies over, so the tuples a check reads are counted.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::Counterexample','struct','Holds the instance, the law and the elements at which a law was not shown, so a failure is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::Decided','struct','Holds how many laws a check decided, on how many tuples and over which elements, so a passing check is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::Law','enum','Names one law of an ordered semiring, so a check and a failure say which law.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::LawCount','struct','Names a number of laws, so a check''s count is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::LawFailure','enum','Names whether a law broke or an operation left the represented elements, with its counterexample, so a refused check is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::Reach','enum','Names whether a check read a whole finite carrier or generated elements, so the scope of its verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::RingLaw','enum','Names one law of a commutative ring, a semiring law or one of the two that a ring adds, so a check and a failure say which law.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::TupleCount','struct','Names a number of tuples a check read, so the check''s work is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::check','function','Decides every law of an ordered semiring on the elements its carrier gives, and returns the first failure with its elements.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::check_law','function','Decides one law of an ordered semiring on the elements its carrier gives, and returns its failure with its elements.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::check_ring','function','Decides every law of a commutative ring on the elements its carrier gives, and returns the first failure with its elements.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','law::check_ring_law','function','Decides one law of a commutative ring on the elements its carrier gives, and returns its failure with its elements.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::Carrier','enum','Holds the elements a check reads, the whole finite carrier or generated elements, so the check knows its reach.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::CommutativeRing','trait','States a commutative ring as an ordered semiring with a negation, so one checker reads every ring.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::Comparison','enum','Names whether one element lies below another in an instance''s order, so the order''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::InstanceName','struct','Names an instance, so each failure says which instance broke.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::OrderedSemiring','trait','States an ordered semiring''s carrier, order, zero, one, addition and multiplication, so one checker reads every instance.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','signature::Outside','struct','Names an operation whose exact result lies past the represented elements, so the law that reads it stays undecided.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','usage::Usage','enum','The number of uses of a hypothesis in the usage semiring {0, 1, omega}: zero, one or many, with an addition, a multiplication and an order.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-ordered-algebras','usage::Usages','struct','Names the usage semiring on its whole carrier, so its laws are checked.',NULL,'fits','sound',NULL);
